create table if not exists public.wishes (id bigint generated by default as identity primary key,name text not null check(char_length(name) between 1 and 150),emoji text not null default '🎁',reserved_by text check(reserved_by is null or char_length(reserved_by) between 1 and 60),sort_order integer not null default 0);
alter table public.wishes enable row level security;
create policy "Anyone can view wishes" on public.wishes for select to anon,authenticated using(true);
create policy "Admin can insert wishes" on public.wishes for insert to authenticated with check(true);
create policy "Admin can update wishes" on public.wishes for update to authenticated using(true) with check(true);
create policy "Admin can delete wishes" on public.wishes for delete to authenticated using(true);
create or replace function public.reserve_wish(wish_id bigint,buyer_name text) returns boolean language plpgsql security definer set search_path='' as $$ begin if buyer_name is null or char_length(trim(buyer_name)) not between 1 and 60 then raise exception 'Ogiltigt namn'; end if; update public.wishes set reserved_by=trim(buyer_name) where id=wish_id and reserved_by is null; return found; end; $$;
revoke all on function public.reserve_wish(bigint,text) from public;
grant execute on function public.reserve_wish(bigint,text) to anon,authenticated;
